{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name, c.span_name, count(*) n, round(avg(c.duration)/1e6,1) client_ms, round(avg(s.duration)/1e6,1) server_ms, round(avg(c.duration-s.duration)/1e6,1) gap_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='search' AND c.span_name='rate.Rate/GetRates' GROUP BY ALL",
          "claim": "search→rate GetRates client spans average about 1777 ms while rate server spans average 0.4 ms, leaving about 1777 ms unaccounted in flight."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name, c.span_name, count(*) n, round(avg(c.duration)/1e6,1) client_ms, round(avg(s.duration)/1e6,1) server_ms, round(avg(c.duration-s.duration)/1e6,1) gap_ms FROM normal_traces c JOIN normal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='search' AND c.span_name='rate.Rate/GetRates' GROUP BY ALL",
          "claim": "In the normal period the same search→rate gap is about 2.7 ms, so the extra time is new in the incident."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(avg(duration)/1e6,2) avg_ms FROM abnormal_traces WHERE service_name='search' AND span_name='geo.Geo/Nearby' AND attr_span_kind='Client' GROUP BY ALL",
          "claim": "Search's calls to geo stay fast (about 0.4 ms), so the slowdown is specific to the search→rate connection."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT s.service_name, s.span_name, round(avg(s.duration)/1e6,2) server_ms FROM abnormal_traces s WHERE s.service_name='rate' AND s.span_name='rate.Rate/GetRates' GROUP BY ALL",
          "claim": "Rate's own server spans stay near 0.4 ms, so the delay is in transit to rate and not in rate's processing."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name, c.span_name, count(*) n, round(avg(c.duration)/1e6,1) client_ms FROM abnormal_traces c WHERE c.service_name='frontend' AND c.span_name='search.Search/Nearby' GROUP BY ALL",
          "claim": "Frontend's search.Search/Nearby client spans average about 1786 ms, up from about 4 ms, matching the slow search server spans."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, round(avg(duration)/1e6,1) avg_ms, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='HTTP /hotels' GROUP BY ALL",
          "claim": "User-facing frontend /hotels requests average about 1788 ms (p95 about 2537 ms), versus about 7 ms normally; other frontend paths stay fast."
        }
      ]
    }
  ]
}
